  const w2y = Math.cos(w1x*0.04+t*0.7)*5 + Math.sin(w1y*0.035+t*0.4)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.15],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.9],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.05],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.65],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.8, 0.8],
    [200+Math.sin(t*0.38+6)*110, 220+Math.cos(t*0.48)*70, 0.075, 2.4, 1.1]
  ];
  let aS = 0, iS = 0, glow = 0;
  for (const [sX, sY, f, sp, amp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * amp;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * amp;
    glow += Math.max(0, 1 - d*0.007) * amp * 0.12;
