  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const sec = Math.sin(act*2.3 - inh*1.7 + t*0.4)*0.18;
  const raw = act - inh*0.65 + bg*0.22 + spiral + cell + sec;
  const reaction = Math.tanh(raw*2.3);
  const edgeGlow = Math.pow(Math.abs(reaction), 3.5) * 2.2;
  const blend = reaction*0.68 + cell*0.16 + sec*0.16;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,48],[10,42,82],[16,95,118],[28,155,145],[85,190,145],
    [180,200,95],[225,185,65],[235,130,70],[210,72,85],[145,38,95],
    [65,15,65],[5,10,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.72 + Math.sin(reaction*Math.PI)*0.28;
  const vig = 1.0 - Math.pow(dist/280, 2.5)*0.3;
  const boost = 1.0 + edgeGlow*0.45 + glow*0.35;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*boost*vig)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*boost*vig)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*boost*vig)|0
  ];
}
